#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> g(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
        }
    }

    vector<bool> rowZero(n, false), colZero(m, false);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (g[i][j] == 0) {
                rowZero[i] = true;
                colZero[j] = true;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cout << (rowZero[i] || colZero[j] ? 0 : g[i][j]) << (j + 1 < m ? " " : "\n");
        }
    }

    return 0;
}

